72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public Integer getNamesakeCount() {
79	        return this.namesakeCount;
80	    }
81	
82	    public void setNamesakeCount(Integer namesakeCount) {
83	        this.namesakeCount = namesakeCount;
