85	
86	    public Boolean getBulkSignupWarning() {
87	        return this.bulkSignupWarning;
88	    }
89	
90	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
91	        this.bulkSignupWarning = bulkSignupWarning;
92	    }
93	
94	    public Integer getHouseholdSize() {
95	        return this.householdSize;
96	    }
97	
98	    public void setHouseholdSize(Integer householdSize) {
99	        this.householdSize = householdSize;
100	    }
101	
102	    public String getCustomerCode() {
103	        return this.customerCode;
104	    }
105	
106	    public void setCustomerCode(String customerCode) {
107	        this.customerCode = customerCode;
108	    }
109	
110	    public String getHouseholdId() {
111	        return this.householdId;
112	    }
113	
114	    public void setHouseholdId(String householdId) {
115	        this.householdId = householdId;
116	    }
117	
118	    public String getEmail() {
119	        return this.email;
120	    }
121	
122	    public void setEmail(String email) {
123	        this.email = email;
124	    }
125	
126	    public String getPostcode() {
127	        return this.postcode;
128	    }
129	
130	    public void setPostcode(String postcode) {
131	        this.postcode = postcode;
132	    }
133	
134	    public LocalDate getRegistrationDate() {
135	        return this.registrationDate;
136	    }
137	
138	    public void setRegistrationDate(LocalDate registrationDate) {
139	        this.registrationDate = registrationDate;
140	    }
141	
142	    public String getAddress() {
143	        return this.address;
144	    }
145	
146	    public void setAddress(String address) {
147	        this.address = address;
148	    }
149	
150	    public String getCity() {
151	        return this.city;
152	    }
153	
154	    public void setCity(String city) {
155	        this.city = city;
156	    }
