164	    }
165	
166	    protected Set<Pet> getPetsInternal() {
167	        if (this.pets == null) {
168	            this.pets = new HashSet<>();
169	        }
170	        return this.pets;
171	    }
172	
173	    protected void setPetsInternal(Set<Pet> pets) {
174	        this.pets = pets;
175	    }
176	
177	    public List<Pet> getPets() {
178	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
179	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
180	        return Collections.unmodifiableList(sortedPets);
181	    }
182	
183	    public void setPets(List<Pet> pets) {
184	        this.pets = new HashSet<>(pets);
185	    }
186	
187	    public void addPet(Pet pet) {
188	        getPetsInternal().add(pet);
189	        pet.setOwner(this);
190	    }
191	
192	    /**
193	     * Return the Pet with the given name, or null if none found for this Owner.
194	     *
195	     * @param name to test
196	     * @return true if pet name is already in use
197	     */
198	    public Pet getPet(String name) {
199	        return getPet(name, false);
