53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
73	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
74	     */
75	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
76	
77	    /**
78	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
79	     * owner's id, customer code, registration date and membership level, so audit side-effects can
80	     * be observed independently of the HTTP response.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys and values are
86	     * upper-cased, matching the state of the address after whitespace and case normalization.
87	     */
88	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
89	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
90	
91	    /**
92	     * Required national-number length per E.164 country calling code. After normalization the leading
93	     * country code is stripped and the remaining national digits must match the expected count exactly
94	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
95	     * here are only subject to the generic E.164 length bounds.
96	     */
97	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
98	        Map.of("1", 10, "61", 9);
99	
100	    /**
101	     * Fixed city-to-region table used to validate an owner's postcode. Cities not listed have no
102	     * known region and accept any well-formed (4-digit) postcode.
103	     */
104	    private static final Map<String, String> CITY_REGION =
105	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
106	
107	    /**
108	     * Inclusive 4-digit postcode range {@code [low, high]} allowed for each region: NSW 2000-2099,
109	     * VIC 3000-3099, QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
110	     */
111	    private static final Map<String, int[]> REGION_POSTCODES =
112	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
113	
114	    private final ClinicService clinicService;
115	
116	    private final OwnerMapper ownerMapper;
117	
118	    private final PetMapper petMapper;
119	
120	    private final VisitMapper visitMapper;
121	
122	    public OwnerRestControllerV1(ClinicService clinicService,
123	                                 OwnerMapper ownerMapper,
124	                                 PetMapper petMapper,
125	                                 VisitMapper visitMapper) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
160	        validateRequiredOwnerFields(ownerFieldsDto);
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
164	        owner.setTelephone(normalizedTelephone);
165	        owner.setEmail(normalizeEmail(owner.getEmail()));
166	        owner.setAddress(normalizeAddress(owner.getAddress()));
167	        validatePostcode(owner.getPostcode(), owner.getCity());
168	        LocalDate effectiveRegistrationDate =
169	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
170	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
171	        rejectDailyLimitReached(owner.getRegistrationDate());
172	        rejectCityAtCapacity(owner.getCity());
173	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
174	            assignHousehold(owner);
175	        }
176	        rejectDuplicateIdentity(owner, normalizedTelephone);
177	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
178	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
179	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
180	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
181	        this.clinicService.saveOwner(owner);
182	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
183	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
184	            ownerMapper.membershipLevel(owner));
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        currentOwner.setAddress(ownerFieldsDto.getAddress());
199	        currentOwner.setCity(ownerFieldsDto.getCity());
200	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
201	        currentOwner.setLastName(ownerFieldsDto.getLastName());
202	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
203	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
204	        this.clinicService.saveOwner(currentOwner);
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        this.clinicService.deleteOwner(owner);
217	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        HttpHeaders headers = new HttpHeaders();
228	        Pet pet = petMapper.toPet(petFieldsDto);
229	        owner.setId(ownerId);
230	        pet.setOwner(owner);
231	        pet.getType().setName(null);
232	        this.clinicService.savePet(pet);
233	        PetDto petDto = petMapper.toPetDto(pet);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
235	            .buildAndExpand(pet.getId()).toUri());
236	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
