328	    /**
329	     * Rejects an owner payload that is missing or blank in any of the required fields
330	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
331	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
332	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
333	     * guard enforces the rule uniformly for every required field.
334	     *
335	     * @param ownerFieldsDto the submitted owner payload
336	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
337	     */
338	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
339	        List<String> invalidFields = new ArrayList<>();
340	        if (isBlank(ownerFieldsDto.getFirstName())) {
341	            invalidFields.add("firstName");
342	        }
343	        if (isBlank(ownerFieldsDto.getLastName())) {
344	            invalidFields.add("lastName");
345	        }
346	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
347	            invalidFields.add("address");
348	        }
349	        if (isBlank(ownerFieldsDto.getCity())) {
350	            invalidFields.add("city");
351	        }
352	        if (isBlank(ownerFieldsDto.getTelephone())) {
353	            invalidFields.add("telephone");
354	        }
355	        if (!invalidFields.isEmpty()) {
356	            throw new InvalidOwnerFieldsException(invalidFields);
357	        }
358	    }
359	
360	    private boolean isBlank(String value) {
361	        return value == null || value.isBlank();
362	    }
363	
364	    /**
365	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
366	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
367	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
368	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
369	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
370	     * and returned exactly as given.
371	     *
372	     * @param postcode the submitted postcode, may be {@code null} when absent
373	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
374	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
375	     */
376	    private void validatePostcode(String postcode, String city) {
377	        if (postcode == null) {
378	            return;
379	        }
380	        if (!postcode.matches("[0-9]{4}")) {
381	            throw new InvalidOwnerFieldsException(List.of("postcode"));
382	        }
383	        String region = city == null ? null : CITY_REGION.get(city);
384	        if (region == null) {
385	            return;
386	        }
387	        int[] range = REGION_POSTCODES.get(region);
388	        int value = Integer.parseInt(postcode);
389	        if (value < range[0] || value > range[1]) {
390	            throw new InvalidOwnerFieldsException(List.of("postcode"));
391	        }
392	    }
393	
394	    /**
395	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
396	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
397	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
398	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
399	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
400	     *
401	     * @param telephone the raw telephone value from the submitted owner payload
402	     * @return the normalized E.164 telephone number
403	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
404	     */
405	    private String normalizeTelephone(String telephone) {
406	        String raw = telephone == null ? "" : telephone.strip();
407	        boolean hasCountryCode = raw.startsWith("+");
408	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
409	        String digits;
410	        if (hasCountryCode) {
411	            digits = cleaned.substring(1);
412	        } else {
413	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
414	            digits = "61" + national;
415	        }
416	        if (!digits.matches("[0-9]{8,15}")) {
417	            throw new InvalidOwnerFieldsException(List.of("telephone"));
418	        }
419	        validateNationalNumberLength(digits);
420	        return "+" + digits;
421	    }
422	
423	    /**
424	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
425	     * country calling code) has the exact length required for that country. The country code is matched
426	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
427	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
428	     *
429	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
430	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
431	     */
432	    private void validateNationalNumberLength(String digits) {
433	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
434	            String countryCode = entry.getKey();
435	            if (digits.startsWith(countryCode)) {
436	                int nationalLength = digits.length() - countryCode.length();
437	                if (nationalLength != entry.getValue()) {
438	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
439	                }
440	                return;
441	            }
442	        }
443	    }
444	
445	    /**
446	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
447	     * returning {@code null} when the value cannot form a valid E.164 number.
448	     *
449	     * @param telephone an existing owner's stored telephone value
450	     * @return the E.164 form, or {@code null} if it cannot be normalized
451	     */
452	    private String toE164OrNull(String telephone) {
453	        try {
454	            return normalizeTelephone(telephone);
455	        } catch (InvalidOwnerFieldsException ex) {
456	            return null;
457	        }
458	    }
459	
460	    /**
461	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
462	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
463	     * accepted value is trimmed and lower-cased before it is stored and returned.
464	     *
465	     * @param email the raw email value from the submitted owner payload, may be {@code null}
466	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
467	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
468	     */
469	    private String normalizeEmail(String email) {
470	        if (email == null) {
471	            return null;
472	        }
473	        String trimmed = email.strip();
474	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
475	            throw new InvalidOwnerFieldsException(List.of("email"));
476	        }
477	        return trimmed.toLowerCase(Locale.ROOT);
478	    }
479	
480	    /**
481	     * Rejects creating an owner whose derived identity key exactly equals that of any existing owner.
482	     * This single check consolidates the former separate telephone, email and household duplicate
483	     * checks: an owner is a duplicate only when its <em>whole</em> identity key
484	     * ({@code '<normalizedTelephone>|<email>|<householdId>'}) matches an existing owner's. Because the
485	     * telephone is part of the key, two members of the same household (same {@code householdId}) with
486	     * different telephones have different identity keys and are both allowed.
487	     *
488	     * <p>The new owner's telephone is already E.164-normalized and its email already lower-cased.
489	     * Existing owners' telephones are converted to E.164 form and their emails lower-cased before the
490	     * key is built, so differently-formatted representations of the same values still collide.
491	     *
492	     * @param owner the owner being created, whose email and household id contribute to the key
493	     * @param normalizedTelephone the E.164 telephone of the owner being created
494	     * @throws DuplicateOwnerIdentityException if another owner already has the same whole identity key
495	     */
496	    private void rejectDuplicateIdentity(Owner owner, String normalizedTelephone) {
497	        String newKey = identityKey(normalizedTelephone, owner.getEmail(), owner.getHouseholdId());
498	        boolean duplicate = this.clinicService.findAllOwners().stream()
499	            .anyMatch(existing -> newKey.equals(identityKey(
500	                toE164OrNull(existing.getTelephone()),
501	                existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT),
502	                existing.getHouseholdId())));
503	        if (duplicate) {
504	            throw new DuplicateOwnerIdentityException(newKey);
505	        }
506	    }
507	
508	    /**
509	     * Builds the duplicate-detection identity key, formatted
510	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The telephone, email and household-id
511	     * segments are each replaced with the empty string when {@code null}, so an absent email or
512	     * household id contributes an empty segment rather than the literal {@code "null"}.
513	     *
514	     * @param normalizedTelephone the E.164 telephone, may be {@code null}
515	     * @param email the lower-cased email, may be {@code null}
516	     * @param householdId the household id, may be {@code null}
517	     * @return the identity key
518	     */
519	    private String identityKey(String normalizedTelephone, String email, String householdId) {
520	        return (normalizedTelephone == null ? "" : normalizedTelephone)
521	            + "|" + (email == null ? "" : email)
522	            + "|" + (householdId == null ? "" : householdId);
523	    }
524	
525	    /**
526	     * The maximum number of owners a single city may contain. Once a city already holds this many
527	     * owners, creating another owner in that city is rejected.
528	     */
529	    private static final int MAX_OWNERS_PER_CITY = 50;
530	
531	    /**
532	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
533	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
534	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
535	     * counting used elsewhere.
536	     *
537	     * @param city the city of the owner being created
538	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
539	     */
540	    /**
541	     * The maximum number of owners that may be registered on a single day. Once this many owners
542	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
543	     */
544	    private static final int MAX_OWNERS_PER_DAY = 100;
545	
546	    /**
547	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
548	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
549	     * registration date of the owner being created.
550	     *
551	     * @param registrationDate the registration date of the owner being created
552	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
553	     */
554	    /**
555	     * Rolls an effective registration date forward onto a business day. A registration date must fall
556	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
557	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
558	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
559	     * count, the membership number's year segment, and so on) uses this adjusted date.
560	     *
561	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
562	     * @return the same date if it is a weekday, otherwise the following Monday
563	     */
564	    private LocalDate rollToBusinessDay(LocalDate date) {
565	        DayOfWeek day = date.getDayOfWeek();
566	        if (day == DayOfWeek.SATURDAY) {
567	            return date.plusDays(2);
568	        }
569	        if (day == DayOfWeek.SUNDAY) {
570	            return date.plusDays(1);
571	        }
572	        return date;
573	    }
574	
575	    private void rejectDailyLimitReached(LocalDate registrationDate) {
576	        long ownersToday = this.clinicService.findAllOwners().stream()
577	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
578	            .count();
579	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
580	            throw new DailyOwnerLimitExceededException(registrationDate);
581	        }
582	    }
583	
584	    /**
585	     * The number of owners that must already share a {@code registrationDate} before a newly created
586	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
587	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
588	     */
589	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
590	
591	    /**
592	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
593	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
594	     * the same registration date at the time this owner is created. Existing owners are counted by their
595	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
596	     * daily create-limit accumulation.
597	     *
598	     * @param registrationDate the registration date of the owner being created
599	     * @return {@code true} if the day already holds more than the threshold number of owners
600	     */
601	    private boolean isBulkSignupDay(LocalDate registrationDate) {
602	        long ownersToday = this.clinicService.findAllOwners().stream()
603	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
604	            .count();
605	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
606	    }
607	
608	    private void rejectCityAtCapacity(String city) {
609	        String normalizedCity = normalizeForComparison(city);
610	        long ownersInCity = this.clinicService.findAllOwners().stream()
611	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
612	            .count();
613	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
614	            throw new OwnerCityCapacityExceededException(city);
615	        }
616	    }
617	
618	    /**
619	     * Assigns the owner being created a household identifier when the request opts into sharing a
620	     * household. The identifier is a stable value derived from the owner's normalized last name and
621	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
622	     * value regardless of creation order. Any already-existing owner in the same household that has no
623	     * identifier yet is back-filled with the same value so the whole household stays consistent.
624	     *
625	     * @param owner the owner being created, whose household id is set in place
626	     */
627	    private void assignHousehold(Owner owner) {
628	        String householdId = householdId(owner.getLastName(), owner.getAddress());
629	        String normalizedLastName = normalizeForComparison(owner.getLastName());
630	        String normalizedAddress = normalizeAddress(owner.getAddress());
631	        for (Owner existing : this.clinicService.findAllOwners()) {
632	            if (existing.getHouseholdId() == null
633	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
634	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
635	                existing.setHouseholdId(householdId);
636	                this.clinicService.saveOwner(existing);
637	            }
638	        }
639	        owner.setHouseholdId(householdId);
640	    }
641	
642	    /**
643	     * Counts how many owners belong to the household the owner being created has just been assigned to,
644	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
645	     * given identifier; the owner being created is added on because it is counted before being persisted.
646	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
647	     * household of one. The value is snapshotted on the owner.
648	     *
649	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
650	     * @return the number of household members, including the owner being created
651	     */
652	    private int countHousehold(String householdId) {
653	        if (householdId == null) {
654	            return 1;
655	        }
656	        long existing = this.clinicService.findAllOwners().stream()
657	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
658	            .count();
659	        return (int) existing + 1;
660	    }
661	
662	    /**
663	     * Derives the stable household identifier for a given last name and address. The value is
664	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
665	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
666	     * the same household therefore always produce the same identifier.
667	     *
668	     * @param lastName the owner's last name
669	     * @param address the owner's address
670	     * @return the stable household identifier
671	     */
672	    private String householdId(String lastName, String address) {
673	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
674	        try {
675	            byte[] digest = MessageDigest.getInstance("SHA-256")
676	                .digest(key.getBytes(StandardCharsets.UTF_8));
677	            StringBuilder hex = new StringBuilder();
678	            for (int i = 0; i < 6; i++) {
679	                hex.append(String.format("%02X", digest[i]));
680	            }
681	            return "HH-" + hex;
682	        } catch (NoSuchAlgorithmException ex) {
683	            throw new IllegalStateException("SHA-256 not available", ex);
684	        }
685	    }
686	
687	    /**
688	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
689	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
690	     * result is lower-cased. A {@code null} value normalizes to the empty string.
691	     *
692	     * @param value the value to normalize, may be {@code null}
693	     * @return the normalized value
694	     */
695	    private String normalizeForComparison(String value) {
696	        if (value == null) {
697	            return "";
698	        }
699	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
700	    }
701	
702	    /**
703	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
704	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
705	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
706	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
707	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
708	     * that is stored, returned, and used for every address comparison (household duplicate detection
709	     * and the shared household id).
710	     *
711	     * @param address the raw address value from the submitted owner payload, may be {@code null}
712	     * @return the normalized address
713	     */
714	    private String normalizeAddress(String address) {
715	        if (address == null) {
716	            return "";
717	        }
718	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
719	        if (collapsed.isEmpty()) {
720	            return "";
721	        }
722	        String[] tokens = collapsed.split(" ");
723	        StringBuilder normalized = new StringBuilder();
724	        for (int i = 0; i < tokens.length; i++) {
725	            if (i > 0) {
726	                normalized.append(' ');
727	            }
728	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
729	        }
730	        return normalized.toString();
731	    }
732	}
